import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    total_value = 0
    for _ in range(n):
        l = int(next(it))
        r = int(next(it))
        total_value += r - l + 1

    if total_value % k == 0:
        print(0)
    else:
        print((k - total_value % k) % k)

if __name__ == "__main__":
    solve()
