n = int(input())
current_dir = []

for _ in range(n):
    line = input().strip()
    if line == 'pwd':
        # Print absolute path
        print('/' + '/'.join(current_dir) + '/')
    else:
        # It's a cd command
        path = line.split(' ', 1)[1]

        # Check if it's an absolute path
        is_absolute = path.startswith('/')

        if is_absolute:
            # Absolute path: reset to root
            current_dir = []
            path = path[1:]  # Remove leading slash

        # Split path by slashes
        components = path.split('/')

        for comp in components:
            if comp == '..':
                # Move up one directory
                if current_dir:
                    current_dir.pop()
            else:
                # Add the directory
                current_dir.append(comp)
