def compute_min_sum(strings):
    n = len(strings)

    # For each position (from right), count which letters appear there
    # Position 1 is the rightmost digit
    position_weights = []
    for i in range(len(strings[0]) - 1, -1, -1):
        # weight of position i+1 (from right)
        position_weights.append(10 ** i)

    # For each letter, compute total weight
    letter_weights = {}
    for ch in 'abcdefghij':
        letter_weights[ch] = 0

    # Also track which letters are first characters
    first_chars = set()
    for s in strings:
        if s:
            first_chars.add(s[0])

    # For each string, compute its value based on current assignment
    def value(s):
        res = 0
        for ch in s:
            res = res * 10 + letter_weights[ch]
        return res

    # Sort letters by total weight descending
    sorted_letters = sorted(letter_weights.keys(), key=lambda x: letter_weights[x], reverse=True)

    # Assign digits to letters
    digit_to_letter = {}
    for d in range(9, -1, -1):
        # Find the best letter (highest weight)
        best_letter = None
        for letter in sorted_letters:
            if letter not in digit_to_letter and (letter not in first_chars or d != 0):
                best_letter = letter
                break

        if best_letter is not None:
            digit_to_letter[best_letter] = d
            letter_weights[best_letter] = 0  # mark as assigned

    # Now compute the total sum
    total = 0
    for s in strings:
        if not s:
            continue
        res = 0
        for ch in s:
            res = res * 10 + digit_to_letter[ch]
        total += res

    return total

