    if not data:
        return

    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        # Read the grid
        grid = []
        for i in range(n):
            row = next(it)
            grid.append([int(c) for c in row])

        # Work from top-left to bottom-right
        operations = []

        # For each cell (i, j)
        for i in range(n):
            for j in range(m):
                # If cell (i, j) needs to be flipped
                if grid[i][j] == 1:
                    # Choose the operation that includes (i, j), (i, j+1), (i+1, j)
                    if j < m - 1 and i < n - 1:
                        # All three cells are within bounds
                        operations.append((i + 1, j + 1, i + 1, j + 2, i + 2, j + 1))
                    elif i == n - 1 and j < m - 1:
                        # Flip (i, j), (i, j+1), (i-1, j)
                        operations.append((i + 1, j + 1, i + 1, j + 2, i, j + 1))
                    elif j == m - 1 and i < n - 1:
                        # Flip (i, j), (i+1, j), (i, j-1)
                        operations.append((i + 1, j + 1, i + 2, j + 1, i + 1, j))
