import sys

def solve() -> None:
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    s, f = map(int, sys.stdin.readline().split())

    # Initialize an array to store the number of participants for each start time t
    # t ranges from 1 to n
    participants = [0] * (n + 1)  # Using 1-indexed

    for i in range(1, n + 1):
        # For timezone i, compute the range of t that makes (t + i - 1) % n in [s, f-1]
        # This means t mod n should be in [s - i + 1, f - i] (mod n)
        start = (s - i + 1) % n
        end = (f - i) % n

        # Handle wrap-around
        if start <= end:
            # Normal interval
            for t in range(start, end + 1):
                participants[t] += a[i - 1]
        else:
            # Wrap around n
            for t in range(start, n + 1):
                participants[t] += a[i - 1]
            for t in range(1, end + 1):
                participants[t] += a[i - 1]

    # Find the start time with maximum participants (smallest index in case of tie)
    max_participants = -1
    best_t = -1
    for t in range(1, n + 1):
        if participants[t] > max_participants:
            max_participants = participants[t]
            best_t = t
        elif participants[t] == max_participants and t < best_t:
            best_t = t

    print(best_t)

if __name__ == "__main__":
    solve()
