            # Cost = minimum differing characters between any substring of t of length len_u and u
            # We only need to compare with u, we can slide through t
            diff = 0
            for i in range(len_t - len_u + 1):
                if i > 0:
                    # Remove the character that's no longer in the window
                    if t[i-1] != u[i-1]:
                        diff -= 1
                # Add the new character at the end of the window
                if t[i+len_u-1] != u[i+len_u-1]:
                    diff += 1
                min_diff = diff
            cost = min_diff
        elif len_t < len_u:
            # Cost = insertions + minimum differing characters between t and any substring of u of length len_t
            insertions = len_u - len_t
            # Compare t with substrings of u of length len_t
            diff = 0
            for i in range(len_t):
                if t[i] != u[i]:
                    diff += 1
            min_diff = diff

