def min_coins(n, k, A, B):
    """Calculate the minimum coins needed to reduce n to 1."""
    if n == 1:
        return 0

    # If k is 1 or subtracting is cheaper than dividing, just subtract all the way
    if k == 1 or A >= B * k:
        return A * (n - 1)

    # Otherwise, we want to divide as much as possible
    # Make n divisible by k by subtracting 1 enough times
    remainder = n % k
    if remainder == 0:
        # n is already divisible by k
        return B + min_coins(n // k, k, A, B)
    else:
        # Subtract to make it divisible by k
        return (k - remainder) * A + B + min_coins(n // k, k, A, B)

