from collections import deque

def solve(x, y):
    if x == y:
        return 0

    # BFS from (x, x, x) to (y, y, y)
    queue = deque([(x, x, x, 0)])
    visited = set()
    visited.add((x, x, x))

    while queue:
        a, b, c, steps = queue.popleft()

        if a == y and b == y and c == y:
            return steps

        # Try changing each side to any integer value
        for i in range(3):
            # Change the i-th side to some value v
            # v must satisfy triangle inequality with the other two sides
            # For sides a, b, c, if we change the i-th side to v:
            # The other two sides are s1 and s2
            s1, s2 = [a, b, c][:(i+1)] + [a, b, c][(i+1):]
            min_val = 1
            max_val = min(s1 + s2 - 1, 100000)  # upper bound to avoid infinite loops

            for v in range(min_val, max_val + 1):
                if i == 0:
                    new_a, new_b, new_c = v, b, c
                elif i == 1:
                    new_a, new_b, new_c = a, v, c
                else:
                    new_a, new_b, new_c = a, b, v

                if (new_a, new_b, new_c) not in visited:
                    visited.add((new_a, new_b, new_c))
                    queue.append((new_a, new_b, new_c, steps + 1))

x, y = map(int, input().split())
print(solve(x, y))
