from collections import deque

def solve(x, y):
    if x == y:
        return 0

    queue = deque([(x, x, x, 0)])
    visited = set()
    visited.add((x, x, x))

    while queue:
        a, b, c, steps = queue.popleft()

        if a == y and b == y and c == y:
            return steps

        # Try changing each side to any integer value
        # Change a to v, keeping b and c
        for v in range(1, min(b + c - 1, 100000) + 1):
            new_state = (v, b, c)
            if new_state not in visited:
                visited.add(new_state)
                queue.append((v, b, c, steps + 1))

        # Change b to v, keeping a and c
        for v in range(1, min(a + c - 1, 100000) + 1):
            new_state = (a, v, c)
            if new_state not in visited:
                visited.add(new_state)
                queue.append((a, v, c, steps + 1))

        # Change c to v, keeping a and b
        for v in range(1, min(a + b - 1, 100000) + 1):
            new_state = (a, b, v)
            if new_state not in visited:
                visited.add(new_state)
                queue.append((a, b, v, steps + 1))

