from collections import Counter

# Helper: Convert a string to its numerical value based on letter assignments
def value(s, assignments):
    v = 0
    for ch in s:
        v = v * 10 + assignments[ch]
    return v

# Helper: Calculate total sum for a given assignment
def total_sum(strings, assignments):
    return sum(value(s, assignments) for s in strings)

# Find the best assignment
def find_best_assignment(strings):
    n = len(strings)

    # Count how many times each letter appears in each position
    pos_counts = [Counter() for _ in range(6)]  # max length is 6

    for i, s in enumerate(strings):
        for j, ch in enumerate(s):
            pos_counts[j][ch] += 1

    # Create a mapping from letter to its weight
    # Weight = (position importance) * (frequency in that position)
    # Position importance: position 0 is most important (10^5 for length 6)
    # We use a simple weighting: position importance = (5 - position)
    letter_weight = {}

    for pos in range(6):
        importance = 5 - pos
        for ch, count in pos_counts[pos].items():
            letter_weight[ch] = letter_weight.get(ch, 0) + importance * count

    # Sort letters by weight (descending), then by letter
    letters = list(letter_weight.keys())
    letters.sort(key=lambda x: (-letter_weight[x], x))

    # Assign digits
    assignments = {}
    for digit in range(10):
        for letter in letters:
            if letter not in assignments:
                assignments[letter] = digit
                break

    return assignments

# Solve the problem
def solve():
    n = int(input())
    strings = [input().strip() for _ in range(n)]

    # Try all possible assignments (for small n)
    # We could use a better approach, but with n up to 1000, we need a smart algorithm

    # Use the greedy approach
    assignment = find_best_assignment(strings)
    total = total_sum(strings, assignment)
    print(total)

solve()
