table = []
for _ in range(n):
    table.append(list(map(int, input().split())))

# Check if a row can be sorted with at most one swap
def can_sort_with_one_swap(row):
    # Find positions where elements are not in order
    misplaced = []
    for i in range(len(row)):
        if row[i] != i + 1:
            misplaced.append(i)

    # If only 0 or 1 element is misplaced, already sorted
    if len(misplaced) <= 1:
        return True

    # If exactly 2 elements are misplaced, check if swapping them works
    if len(misplaced) == 2:
        i, j = misplaced
        if row[i] == j + 1 and row[j] == i + 1:
            return True

    return False

# Check if all rows can be sorted with at most one swap (no column swap)
if all(can_sort_with_one_swap(row) for row in table):
    print("YES")
else:
    # Try all possible column swaps
    for i in range(m):
        for j in range(i + 1, m):
            # Create a new table with columns i and j swapped
            new_table = []
            for row in table:
                new_row = row.copy()
                new_row[i], new_row[j] = new_row[j], new_row[i]
                new_table.append(new_row)

            # Check if all rows can be sorted with at most one swap after this column swap
            if all(can_sort_with_one_swap(row) for row in new_table):
                print("YES")
                exit()

    print("NO")
