def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
    return True

n, m = map(int, input().split())
parent = list(range(n + 1))
rank = [1] * (n + 1)

# Count nodes and edges in each component
component_info = {}
for _ in range(m):
    x, y = map(int, input().split())
    px = find(parent, x)
    py = find(parent, y)
    # Union the components
    union(parent, rank, x, y)
    # Count nodes in this component
    count = 0
    for i in range(1, n + 1):
        if find(parent, i) == px:
            count += 1
    component_info[px] = count

# Calculate result
