import sys

def is_maximal(seating):
    n = len(seating)

    # Check if there are any two consecutive 1s
    for i in range(n - 1):
        if seating[i] == '1' and seating[i + 1] == '1':
            return False

    # Check if there's any 0 that can be occupied
    for i in range(n):
        if seating[i] == '0':
            # Check left neighbor
            left_ok = (i == 0) or (seating[i - 1] == '0')
            # Check right neighbor
            right_ok = (i == n - 1) or (seating[i + 1] == '0')
            if left_ok and right_ok:
                return False

