import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # DSU implementation
    parent = list(range(n + 1))  # 1-indexed
    size = [1] * (n + 1)

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # path compression
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        # Union by size
        if size[u_root] < size[v_root]:
            u_root, v_root = v_root, u_root
        parent[v_root] = u_root
        size[u_root] += size[v_root]

    for _ in range(m):
        k = int(next(it))
        if k == 0:
            continue
        users = [int(next(it)) for _ in range(k)]
        if k == 1:
            continue
        # Take the first user as representative
        rep = users[0]
        for user in users[1:]:
            union(rep, user)

    # Find component sizes
    result = []
    for i in range(1, n + 1):
        result.append(str(size[find(i)]))

    print(' '.join(result))

if __name__ == '__main__':
    solve()
