import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    q = int(next(it))
    s = next(it)
    t = next(it)

    if m > n:
        for _ in range(q):
            print(0)
        return

    # Count occurrences of t in s (1-indexed)
    occ = [0] * (n + 1)  # occ[i] = count of occurrences starting at position i

    for i in range(n - m + 1):
        if s[i:i+m] == t:
            occ[i+1] = 1

    # prefix sum
    pre = [0] * (n + 1)
    for i in range(1, n + 1):
        pre[i] = pre[i-1] + occ[i]

    out_lines = []
    for _ in range(q):
        l = int(next(it))
        r = int(next(it))
        # valid start positions: from l to r - m + 1, inclusive
        start = r - m + 1
        if start < l or start < 1:
            out_lines.append('0')
        else:
            ans = pre[start] - pre[l - 1]
            out_lines.append(str(ans))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
"}

