from math import gcd

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    b = list(map(int, data[n+1:2*n+1]))

    always_zero = 0
    freq = {}

    for ai, bi in zip(a, b):
        if ai == 0 and bi == 0:
            always_zero += 1
        elif ai != 0:
            # Reduce the fraction -bi/ai
            # Find gcd of bi and ai
            g = gcd(bi, ai)

            # Simplify both numerator and denominator
            num = bi // g
            den = ai // g

            # Ensure consistent sign: denominator should be positive
            # If denominator is negative, swap numerator and denominator and negate
            if den < 0:
                num = -num
                den = -den

            # Store in reduced form
            freq[(num, den)] = freq.get((num, den), 0) + 1

    if always_zero == n:
        print(n)
    elif freq:
        max_freq = max(freq.values())
        print(max_freq + always_zero)
    else:
        print(always_zero)

