def cost(p, l, r):
    """Calculate cost when at position p for interval [l, r]"""
    if l <= p <= r:
        return 0
    if p < l:
        return l - p
    return p - r

def solve() -> None:
    """Read input, solve, and print result"""
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    x = int(data[1])
    intervals = []
    idx = 2

    for _ in range(n):
        l = int(data[idx])
        r = int(data[idx + 1])
        intervals.append((l, r))
        idx += 2

    # DP: dp[i][p] = minimum cost from turn i to end when at position p before turn i
    # We'll use a dictionary of dictionaries
    dp = {}

    # Base case: after last turn
    dp[n] = {}

    # Fill DP from last turn to first turn
    for i in range(n, 0, -1):
        l, r = intervals[i - 1]

        # For each possible position p, find min cost
        dp[i] = {}
        for pos in dp[i + 1]:
            # Consider moving from pos to new_pos at cost |new_pos - pos|
            # Then pay cost based on new_pos

            # Actually, we need to decide our position before turn i
            # So we should consider all possible new_pos

            # Let's consider all positions from max(1, l - 10) to min(r + 10, 10**9)
            # We only need to consider positions near the interval [l, r]
            # because moving far away would be inefficient

            for new_pos in range(max(1, l - 10), min(10**9, r + 10) + 1):
                if i == n:
                    # Last turn
                    dp[i][new_pos] = cost(new_pos, l, r)
                else:
                    # Move from pos to new_pos
                    move_cost = abs(new_pos - pos)
                    light_cost = cost(new_pos, l, r)
                    total = move_cost + light_cost + dp[i + 1][pos]
                    if new_pos not in dp[i] or total < dp[i][new_pos]:
