import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    front_counts = {}
    back_counts = {}

    index = 1
    for i in range(n):
        front = int(data[index])
        back = int(data[index + 1])
        index += 2

        front_counts[front] = front_counts.get(front, 0) + 1
        back_counts[back] = back_counts.get(back, 0) + 1

    min_flips = float('inf')

    # Try each color that appears on either side
    for color in front_counts:
        # Count how many cards show this color on front (no flip needed)
        count_front = front_counts[color]
        # Count how many cards have this color on back (flip needed)
        count_back = back_counts.get(color, 0)

        # How many more cards we need to get to at least half
        required = max(0, (n + 1) // 2 - count_front)

        # If we can get the required number by flipping back cards
        if count_back >= required:
            min_flips = min(min_flips, required)

    # Also check colors that only appear on the back
    for color in back_counts:
        if color not in front_counts:
            count_front = 0
            count_back = back_counts[color]

            required = max(0, (n + 1) // 2 - count_front)

            if count_back >= required:
                min_flips = min(min_flips, required)

    if min_flips == float('inf'):
        print(-1)
    else:
        print(min_flips)

if __name__ == "__main__":
    solve()
