import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    a = int(next(it))
    n = int(next(it))
    m = int(next(it))

    rain_segments = []
    for _ in range(n):
        l = int(next(it))
        r = int(next(it))
        rain_segments.append((l, r))

    umbrellas = []
    for _ in range(m):
        x = int(next(it))
        p = int(next(it))
        umbrellas.append((x, p))

    # DP: dp[x] is a dictionary mapping set of umbrellas (represented by indices) to minimum fatigue
    # But with m=2000, we need a more efficient approach

    # Instead, let's use dp[x] = minimum fatigue to reach position x with a set of umbrellas
    # We can represent the set of umbrellas more efficiently

    # Actually, we can use a greedy approach:
    # - Pick up umbrellas at positions before rain segments
    # - Carry umbrellas through rain segments
    # - Drop umbrellas after rain segments

    # Let's try a DP where we track the set of umbrellas we carry
    # But we need a more efficient representation

    # Let's use a dictionary where keys are frozensets of umbrella indices
    dp = [{} for _ in range(a + 2)]  # dp[x] maps set of umbrellas to fatigue

    # Start at position 0 with no umbrellas
    dp[0][frozenset()] = 0

    for x in range(a):
        if x in dp:
            for umb_set, fatigue in dp[x].items():
                # Move to x+1
                new_set = umb_set
                if [x, x+1] is in rain:
                    # Must have at least one umbrella
                    if not umb_set:
                        continue  # Can't move without umbrella

                # Calculate fatigue for this move
                fatigue_cost = sum(umbrellas[i][1] for i in umb_set)

                # Check if we can move to x+1
                if [x, x+1] in rain_segments:
                    if not umb_set:
                        continue

                # Move to x+1
                dp[x+1][new_set] = min(dp[x+1].get(new_set, float('inf')), fatigue + fatigue_cost)

    # Also consider picking up umbrellas at position x
    for x in range(a):
        if x in dp:
            for umb_set, fatigue in dp[x].items():
                # Consider picking up umbrellas at x
                for i, (pos, _) in enumerate(umbrellas):
                    if pos == x:
                        new_set = umb_set | {i}
                        new_fatigue = fatigue + umbrellas[i][1]  # Carrying this umbrella costs its weight
                        dp[x][new_set] = min(dp[x].get(new_set, float('inf')), new_fatigue)

    # Also consider dropping umbrellas
    for x in range(a):
        if x in dp:
            for umb_set, fatigue in dp[x].items():
                for i in umb_set:
                    new_set = umb_set - {i}
                    new_fatigue = fatigue  # Dropping doesn't cost anything
                    dp[x][new_set] = min(dp[x].get(new_set, float('inf')), new_fatigue)

    # Check if we can reach position a
    if a in dp and dp[a]:
        print(min(dp[a].values()))
    else:
        print(-1)

solve()
