import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    a = int(next(it))
    n = int(next(it))
    m = int(next(it))

    rain_segments = set()
    for _ in range(n):
        l = int(next(it))
        r = int(next(it))
        rain_segments.add((l, r))

    umbrellas = []
    for _ in range(m):
        x = int(next(it))
        p = int(next(it))
        umbrellas.append((x, p))

    # DP: dp[x] is a dictionary mapping set of umbrella indices to minimum fatigue
    dp = [{} for _ in range(a + 2)]  # dp[x] maps set of umbrellas to fatigue

    # Start at position 0 with no umbrellas
    dp[0][frozenset()] = 0

    # First, we need to pick up umbrellas at positions before rain segments
    # Let's consider the strategy: at each position x, decide which umbrellas to pick up
    for x in range(a):
        if x in dp:
            for umb_set, fatigue in dp[x].items():
                # Move to x+1 with current umbrellas
                move = (x, x+1)
                if move in rain_segments:
                    if umb_set:
                        fatigue_cost = sum(umbrellas[i][1] for i in umb_set)
                        dp[x+1][umb_set] = min(dp[x+1].get(umb_set, float('inf')), fatigue + fatigue_cost)
                    else:
                        # No umbrella, can't move
                        pass
                else:
                    # No rain, can move without umbrella
                    dp[x+1][umb_set] = min(dp[x+1].get(umb_set, float('inf')), fatigue)

    # Now consider picking up umbrellas at position x
    for x in range(a):
        if x in dp:
            for umb_set, fatigue in dp[x].items():
                # Consider picking up umbrellas at x
                for i, (pos, _) in enumerate(umbrellas):
                    if pos == x:
                        new_set = umb_set | {i}
                        new_fatigue = fatigue + umbrellas[i][1]  # Carrying this umbrella costs its weight
                        # Move to x+1 with the new set of umbrellas
                        move = (x, x+1)
                        if move in rain_segments:
                            fatigue_cost = sum(umbrellas[j][1] for j in new_set)
                            dp[x+1][new_set] = min(dp[x+1].get(new_set, float('inf')), new_fatigue + fatigue_cost)
                        else:
                            dp[x+1][new_set] = min(dp[x+1].get(new_set, float('inf')), new_fatigue)

    # Consider dropping umbrellas
    for x in range(a):
        if x in dp:
            for umb_set, fatigue in dp[x].items():
                for i in umb_set:
                    new_set = umb_set - {i}
                    new_fatigue = fatigue  # Dropping doesn't cost anything
                    # Move to x+1 with the new set of umbrellas
                    move = (x, x+1)
                    if move in rain_segments:
                        if new_set:
                            fatigue_cost = sum(umbrellas[j][1] for j in new_set)
                            dp[x+1][new_set] = min(dp[x+1].get(new_set, float('inf')), new_fatigue + fatigue_cost)
                    else:
                        dp[x+1][new_set] = min(dp[x+1].get(new_set, float('inf')), new_fatigue)

    # Check if we can reach position a
    if a in dp and dp[a]:
        print(min(dp[a].values()))
    else:
        print(-1)

