        # First trolleybus
        if vi ** 2 >= 2 * a * d:
            # Doesn't reach max speed
            time_to_reach = math.sqrt(2 * d / a)
        else:
            # Reaches max speed
            time_to_reach = 0.5 * vi / a + d / vi
        arrival_time = ti + time_to_reach
    else:
        # Subsequent trolleybuses
        # Calculate arrival time if no obstruction
        if vi ** 2 >= 2 * a * d:
            time_to_reach = math.sqrt(2 * d / a)
        else:
            time_to_reach = 0.5 * vi / a + d / vi
        arrival_time = ti + time_to_reach

        # Check if catches up with previous
        if arrival_time < results[i-1]:
            arrival_time = results[i-1]

    results.append(arrival_time)

for result in results:
    print(f"{result:.9f}")
