def get_min_sum(n, strings):

    # Count contribution of each letter
    contributions = {}
    # Track which letters cannot be 0 (first characters)
    cannot_be_zero = set()

    for i, s in enumerate(strings):
        # Position weights: 10^position
        weights = [10 ** (len(s) - 1 - j) for j in range(len(s))]

        for j, c in enumerate(s):
            contribution = contributions.get(c, 0) + weights[j]
            contributions[c] = contribution

            # If this is the first character, cannot be 0
            if i == 0:
                cannot_be_zero.add(c)

    # Sort letters by contribution (descending)
    letters = sorted(contributions.keys(), key=lambda x: contributions[x], reverse=True)

    # Assign digits
    assigned_digits = {}
    remaining_digits = set(range(10))

    # First, assign 0 to a letter that CAN be 0
    first_zero_letter = None
    for letter in letters:
        if letter not in cannot_be_zero:
            first_zero_letter = letter
            break

    if first_zero_letter:
        assigned_digit = min(remaining_digits)
        assigned_digits[first_zero_letter] = assigned_digit
        remaining_digits.remove(assigned_digit)

    # Then assign remaining letters, removing 0 for first character letters
    for letter in letters:
        if letter in cannot_be_zero:
            if 0 in remaining_digits:
                remaining_digits.remove(0)

        assigned_digit = min(remaining_digits)
        assigned_digits[letter] = assigned_digit
        remaining_digits.remove(assigned_digit)

    # Calculate sum
    total = 0
    for s in strings:
        num = 0
        for c in s:
            num = num * 10 + assigned_digits[c]
        total += num

    return total

n = int(input())
strings = [input().strip() for _ in range(n)]

print(get_min_sum(n, strings))
