import sys

def min_changes(s, u):
    n = len(s)
    m = len(u)
    min_cost = float('inf')

    # Create a 2D array where diff[i][j] = number of differences between s[i] and u[j]
    diff = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            diff[i][j] = 1 if s[i] != u[j] else 0

    # Precompute prefix sums for each row of diff
    prefix = [[0] * (m + 1) for _ in range(n)]
    for i in range(n):
        for j in range(1, m + 1):
            prefix[i][j] = prefix[i][j - 1] + diff[i][j - 1]

    # Now try all substrings of s
    for i in range(n):
        for j in range(i, n):
            k = j - i + 1
            cost = abs(k - m)

            if k > m:
                # Compare with u of length m
                # Find the best match in this substring
                best = float('inf')
                for start in range(k - m + 1):
                    # Calculate differences between u[0:m] and s[i+start:i+start+m]
                    # This is prefix[i+start+m] - prefix[i+start] for the first m positions
                    diff_count = 0
                    for l in range(m):
                        diff_count += diff[i + start + l][l]
