# Convert positions to (column, row) where 'a'-'h' -> 0-7, '1'-'8' -> 0-7
def parse_pos(pos):
    col = ord(pos[0]) - ord('a')
    row = int(pos[1]) - 1
    return (col, row)

rook1 = parse_pos(rook1_pos)
rook2 = parse_pos(rook2_pos)
white_king = parse_pos(white_king_pos)
black_king = parse_pos(black_king_pos)

# Check if black king is attacked
def is_attacked(pos):
    col, row = pos
    # Check if attacked by white rook 1
    if (col == rook1[0] or row == rook1[1]) and not is_blocked(rook1, pos):
        return True
    # Check if attacked by white rook 2
    if (col == rook2[0] or row == rook2[1]) and not is_blocked(rook2, pos):
        return True
    # Check if attacked by white king
    if abs(col - white_king[0]) <= 1 and abs(row - white_king[1]) <= 1:
        return True
    return False

# Check if there's a piece blocking the attack path
def is_blocked(attacker, target):
    a_col, a_row = attacker
    t_col, t_row = target

    # If same column, check if any piece in between
    if a_col == t_col:
        min_row, max_row = sorted([a_row, t_row])
        for r in range(min_row + 1, max_row):
            if (a_col, r) == rook1 or (a_col, r) == rook2 or (a_col, r) == white_king or (a_col, r) == black_king:
                return True
    # If same row, check if any piece in between
    elif a_row == t_row:
        min_col, max_col = sorted([a_col, t_col])
        for c in range(min_col + 1, max_col):
            if (c, a_row) == rook1 or (c, a_row) == rook2 or (c, a_row) == white_king or (c, a_row) == black_king:
                return True
    return False

# Check if black king is in check
in_check = is_attacked(black_king)

# Check if black king has any legal moves to escape check
def has_escape_moves():
    col, row = black_king
    # Check all 8 adjacent squares
    for dcol in [-1, 0, 1]:
        for drow in [-1, 0, 1]:
            if dcol == 0 and drow == 0:
                continue  # Current position
            new_col = col + dcol
            new_row = row + drow

            # Check if on the board
            if 0 <= new_col < 8 and 0 <= new_row < 8:
                # Check if square is empty
                if (new_col, new_row) not in [rook1, rook2, white_king, black_king]:
                    # Check if square is attacked
                    if not is_attacked((new_col, new_row)):
                        return True
    return False

if in_check and not has_escape_moves():
    print("CHECKMATE")
else:
    print("OTHER")
