from collections import defaultdict, deque

def solve():
    n, m = map(int, input().split())

    # Build adjacency list
    adj = defaultdict(list)

    for _ in range(m):
        parts = list(map(int, input().split()))
        k = parts[0]
        users = parts[1:]

        # Connect all pairs in this group
        for i in range(k):
            for j in range(i + 1, k):
                adj[users[i]].append(users[j])

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = [0] * (n + 1)

    for user in range(1, n + 1):
        if not visited[user]:
            # BFS to find component size
            queue = deque([user])
            visited[user] = True
            size = 0

            while queue:
                current = queue.popleft()
                size += 1

                for friend in adj[current]:
                    if not visited[friend]:
                        visited[friend] = True
                        queue.append(friend)

            # Record component size for all users in this component
            for user_in_component in range(1, n + 1):
                if visited[user_in_component]:
                    component_sizes[user_in_component] = size

    # Output results
    print(' '.join(map(str, component_sizes[1:])))

solve()
