import sys

def count_operations(n, arr):
    operations = 0

    while n > 0:
        # Find the longest segment (leftmost if tied)
        max_len = 0
        segment_start = 0

        for i in range(n):
            if i == 0 or arr[i] != arr[i-1]:
                # Start of a new segment
                current_value = arr[i]
                current_len = 1

                for j in range(i+1, n):
                    if arr[j] == current_value:
                        current_len += 1
                    else:
                        break

                if current_len > max_len or (current_len == max_len and i < segment_start):
                    max_len = current_len
                    segment_start = i

        # Remove the segment
        n -= max_len
        operations += 1

        # Update the array (slice)
        arr = arr[:segment_start] + arr[segment_start + max_len:]

    return operations

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    result = count_operations(n, arr)
    print(result)

if __name__ == "__main__":
    main()
