n = int(input())
seating = input().strip()

# Check condition 1: no two 1s are adjacent
for i in range(n - 1):
    if seating[i] == '1' and seating[i+1] == '1':
        print("No")
        exit()

# Check condition 2: every 0 is adjacent to at least one 1
for i in range(n):
    if seating[i] == '0':
        # Check left neighbor (if exists)
        if i > 0 and seating[i-1] == '1':
            continue
        # Check right neighbor (if exists)
        if i < n - 1 and seating[i+1] == '1':
            continue
        # Neither neighbor is occupied
        print("No")
        exit()

print("Yes")
